// Failover de juguete con procesos reales: primario, standby y un "router" con health check.
const { spawn } = require('child_process'); const http = require('http');
const srv = (nombre, puerto) => spawn(process.execPath, ['-e', `require('http').createServer((q,r)=>r.end('${nombre}')).listen(${puerto},'127.0.0.1')`]);
const prim = srv('primario', 25881), stand = srv('standby', 25882);
let activo = 25881, fallos = 0; const t0 = () => Date.now();
const get = (p, ms) => new Promise(res => { const r = http.get({ host: '127.0.0.1', port: p, path: '/', timeout: ms }, x => { let b = ''; x.on('data', d => b += d); x.on('end', () => res(b)); }); r.on('error', () => res(null)); r.on('timeout', () => { r.destroy(); res(null); }); });
// health check: cada 200 ms mira al activo; 3 fallos seguidos => cambia
setInterval(async () => { if (await get(activo, 150)) fallos = 0; else if (++fallos >= 3 && activo === 25881) { activo = 25882; console.log('router: health check falló 3 veces, paso a standby'); } }, 200);
const sleep = ms => new Promise(r => setTimeout(r, ms));
(async () => {
  await sleep(800);
  let caido = null, vuelta = null, ok = 0, mal = 0, tKill;
  const fin = t0() + 4000;
  setTimeout(() => { tKill = t0(); prim.kill('SIGKILL'); console.log('primario: muerto (SIGKILL)'); }, 1000);
  while (t0() < fin) {
    const r = await get(activo, 100);
    if (r) { ok++; if (tKill && caido && !vuelta) { vuelta = t0(); } } else { mal++; if (tKill && !caido) caido = t0(); }
    await sleep(50);
  }
  console.log(`pedidos ok=${ok} fallidos=${mal}`);
  console.log(`tiempo sin servicio visto por el cliente: ${vuelta - caido} ms (RTO medido en esta VM)`);
  stand.kill('SIGKILL'); process.exit();
})();

// RPO de juguete con tiempo simulado: llega 1 escritura cada 10 ms y el primario se cae en t = 5000 ms.
function simular(modo, retrasoMs, rttMs) {
  const caida = 5000; let confirmadas = 0, enReplica = 0, perdidas = 0;
  for (let t = 0; t < caida; t += 10) {
    if (modo === "sincrona") {
      // se confirma al cliente recién cuando la réplica ya la tiene (suma un viaje de ida y vuelta)
      if (t + rttMs <= caida) { confirmadas++; enReplica++; }
    } else {
      confirmadas++;                       // se confirma al instante
      if (t + retrasoMs <= caida) enReplica++; // la réplica la recibe después
    }
  }
  perdidas = confirmadas - enReplica;
  return { confirmadas, enReplica, perdidas, rpoMs: perdidas * 10 };
}
const casos = [["asíncrona, retraso 20 ms", "asincrona", 20, 0], ["asíncrona, retraso 500 ms", "asincrona", 500, 0], ["asíncrona, retraso 1 s", "asincrona", 1000, 0], ["síncrona, viaje 2 ms", "sincrona", 0, 2], ["síncrona, viaje 70 ms", "sincrona", 0, 70]];
for (const [n, m, r, rtt] of casos) { const x = simular(m, r, rtt); console.log(n.padEnd(28), "confirmadas:", String(x.confirmadas).padStart(3), "| perdidas:", String(x.perdidas).padStart(3), "| ventana de datos perdidos ≈", x.rpoMs, "ms"); }
console.log("Costo de la síncrona: cada escritura espera el viaje de ida y vuelta (2 ms en una zona vecina, 70 ms entre regiones lejanas, valores inventados para el ejemplo).");

// Calculadora de juguete. TODOS los números son inventados para una API de seguimiento de envíos ficticia.
